#!/usr/bin/env bash
set -euo pipefail
ROOT_DIR="$(cd "$(dirname "${BASH_SOURCE[0]}")/.." && pwd)"; source "$ROOT_DIR/scripts/lib/common.sh"; source "$ROOT_DIR/scripts/lib/nginx.sh"; DOMAIN="${1:-}"
if ! have nginx; then echo 'Nginx: not installed'; exit 0; fi
printf 'Nginx: %s\n' "$(nginx -v 2>&1)"; inspect_nginx || die 'nginx -T failed. Run: sudo nginx -t'; printf 'HTTP :80: %s\nSTREAM :80: %s\nHTTP :443: %s\nSTREAM :443: %s\nssl_preread: %s\nproxy_protocol: %s\n' "$(nginx_json_bool http_80)" "$(nginx_json_bool stream_80)" "$(nginx_json_bool http_443)" "$(nginx_json_bool stream_443)" "$(nginx_json_bool stream_443_ssl_preread)" "$(nginx_json_bool stream_443_proxy_protocol)"; INNER="$(nginx_inner_https_listener)"; printf 'Local TLS port: %s\n' "${INNER:-not detected}"; if [[ -n "$DOMAIN" ]]; then echo; echo "Existing vhost files for $DOMAIN:"; FILES="$(nginx_domain_files "$DOMAIN" || true)"; [[ -n "$FILES" ]] && printf '%s\n' "$FILES" | sed 's/^/  - /' || echo '  none'; echo; echo 'Matching certificate candidates:'; CERTS="$(find_matching_certs "$DOMAIN" || true)"; [[ -n "$CERTS" ]] && while IFS='|' read -r _ cert key end; do printf '  - cert: %s\n    key: %s\n    until: %s\n' "$cert" "$key" "$end"; done <<<"$CERTS" || echo '  none'; fi
